import json
from pathlib import Path
rows=[]
def add(date,code,title,year,summary,url,ref,source='Source institutionnelle'):
 rows.append(dict(date=date,code=code,title=title,year=year,summary=summary,url=url,source_title=source,evidence='Date et événement explicitement attestés dans la source consultée ; '+ref,confidence='high'))
add('10-01','NGA','Le Nigeria devient indépendant',1960,'Le Nigeria accède à l’indépendance le 1er octobre 1960. Ce jalon met fin à la domination coloniale britannique ; la république sera proclamée trois ans plus tard.','https://fmino.gov.ng/nigerias-independence-day/','turn169search0','Ministère nigérian de l’Information')
add('10-02','GIN','La Guinée proclame son indépendance',1958,'Le 2 octobre 1958, l’Assemblée nationale proclame la République de Guinée. Ce choix suit le rejet de la nouvelle Constitution française lors du référendum de septembre.','https://history.state.gov/historicaldocuments/frus1958-60v14/d56','turn180search5','Office of the Historian — archives diplomatiques')
add('10-03','DEU','La réunification allemande',1990,'Le 3 octobre 1990, la réunification allemande devient effective. La date marque l’adhésion des Länder de l’ancienne Allemagne de l’Est à la République fédérale.','https://www.bundesregierung.de/breg-de/schwerpunkte/deutsche-einheit/die-einheit-ist-wirklichkeit-432814','turn169search6','Gouvernement fédéral allemand')
add('10-04','LSO','L’indépendance du Lesotho',1966,'Le Basutoland devient indépendant le 4 octobre 1966 sous le nom de Lesotho. Ce royaume enclavé dans l’Afrique du Sud était auparavant sous administration britannique.','https://history.state.gov/countries/lesotho','turn172view1','Office of the Historian')
add('10-05','PRT','La République portugaise est proclamée',1910,'La révolution du 5 octobre 1910 renverse la monarchie portugaise. La proclamation de la république ouvre une nouvelle période institutionnelle dans l’histoire du pays.','https://cultura.marinha.pt/en/museumarinha_web/colecoes_web/pecasemdestaque_web/Pages/bandeira-revolucao-republicana.aspx','turn175search18','Musée de la Marine portugaise')
add('10-06','EGY','Le début de la guerre d’octobre',1973,'Le 6 octobre 1973, les forces égyptiennes et syriennes attaquent les forces israéliennes dans le Sinaï et sur le Golan. L’Égypte joue un rôle direct dans cette guerre qui transformera les relations régionales.','https://history.state.gov/milestones/1969-1976/arab-israeli-war-1973','turn177search27','Office of the Historian')
add('10-07','DEU','La fondation de la RDA',1949,'La République démocratique allemande est proclamée le 7 octobre 1949. La création de cet État à l’Est consolide la division de l’Allemagne pendant la guerre froide.','https://www.bundesfinanzministerium.de/Web/EN/About/History/history.html','turn175search20','Ministère fédéral allemand des Finances')
add('10-08','HRV','La Croatie rompt ses liens étatiques avec la Yougoslavie',1991,'Le 8 octobre 1991, le Parlement croate décide de rompre les liens étatiques et juridiques avec la Yougoslavie. Cette décision intervient après la déclaration d’indépendance de juin et un moratoire de trois mois.','https://www.sabor.hr/en/about-parliament/history/important-dates/8-october-croatian-parliament-day','turn175search5','Parlement croate')
add('10-09','UGA','L’indépendance de l’Ouganda',1962,'L’Ouganda accède à l’indépendance le 9 octobre 1962. L’ancien protectorat britannique devient un État souverain.','https://history.state.gov/countries/uganda','turn172view2','Office of the Historian')
add('10-10','FJI','L’indépendance des Fidji',1970,'Le 10 octobre 1970, les Fidji deviennent indépendantes. Cette date marque la fin de la période coloniale britannique dans cet archipel du Pacifique.','https://history.state.gov/countries/fiji','turn172view3','Office of the Historian')
add('10-11','USA','Apollo 7 décolle',1968,'Apollo 7 est lancé le 11 octobre 1968. Premier vol habité du programme Apollo, il permet de tester en orbite terrestre les systèmes nécessaires aux futures missions lunaires.','https://www.nasa.gov/mission/apollo-7/','turn175search0','NASA')
add('10-12','GNQ','L’indépendance de la Guinée équatoriale',1968,'La Guinée équatoriale devient indépendante de l’Espagne le 12 octobre 1968. Ce jalon concerne ses territoires continentaux et insulaires.','https://history.state.gov/countries/equatorial-guinea','turn172view4','Office of the Historian')
add('10-13','USA','La première pierre de la Maison-Blanche',1792,'La première pierre de la résidence présidentielle américaine est posée le 13 octobre 1792. La construction s’inscrit dans l’aménagement de la nouvelle capitale fédérale.','https://www.loc.gov/item/today-in-history/october-13/?loclr=iloc','turn177search1','Library of Congress')
add('10-14','GBR','La bataille de Hastings',1066,'Le 14 octobre 1066, Guillaume de Normandie affronte et vainc l’armée du roi Harold à Hastings. Cette bataille ouvre la voie à la conquête normande de l’Angleterre.','https://www.english-heritage.org.uk/visit/places/1066-battle-of-hastings-abbey-and-battlefield/history-and-stories/history','turn177search2','English Heritage')
add('10-15','BFA','L’assassinat de Thomas Sankara',1987,'Le président Thomas Sankara et douze de ses compagnons sont tués le 15 octobre 1987. Cet événement met fin à la période révolutionnaire qu’il avait conduite au Burkina Faso.','https://memorialsankara.bf/memorial/presentation/','turn186search1','Mémorial Thomas Sankara')
add('10-16','USA','Le raid de John Brown à Harpers Ferry',1859,'Le 16 octobre 1859, John Brown et ses compagnons attaquent l’arsenal fédéral de Harpers Ferry. Cette action abolitionniste devient un épisode majeur des tensions précédant la guerre de Sécession.','https://www.nps.gov/people/john-brown.htm','turn180search35','National Park Service')
add('10-17','FRA','La répression du 17 octobre à Paris',1961,'Le 17 octobre 1961, une manifestation d’Algériens à Paris est violemment réprimée par la police. Cet événement meurtrier appartient à l’histoire de la guerre d’Algérie et à celle de la France.','https://www.elysee.fr/emmanuel-macron/2021/10/16/ceremonie-de-commemoration-des-60-ans-du-17-octobre-1961','turn177search5','Présidence de la République française')
add('10-18','AZE','L’acte d’indépendance de l’Azerbaïdjan',1991,'L’acte constitutionnel sur l’indépendance de l’Azerbaïdjan est adopté le 18 octobre 1991. Il intervient pendant la désagrégation de l’Union soviétique.','https://president.az/en/pages/view/azerbaijan/holidays/','turn180search0','Présidence de l’Azerbaïdjan')
add('10-19','USA','La capitulation de Yorktown',1781,'Le 19 octobre 1781, les forces britanniques de Yorktown capitulent devant les forces américaines et françaises. Cette victoire est un tournant de la guerre d’indépendance américaine.','https://www.nps.gov/york/learn/historyculture/siegetimeline.htm','turn180search2','National Park Service')
add('10-20','KEN','L’état d’urgence dans le Kenya colonial',1952,'Le 20 octobre 1952, l’administration britannique proclame l’état d’urgence au Kenya. Cette mesure ouvre une phase de répression et de guerre liée au mouvement Mau Mau.','https://www.bailii.org/ew/cases/EWHC/QB/2018/2066.html','turn189search0','High Court of Justice — jugement Kimathi')
add('10-21','GBR','La bataille de Trafalgar',1805,'Le 21 octobre 1805, la flotte britannique affronte les flottes française et espagnole à Trafalgar. Cette bataille navale majeure appartient à l’histoire des guerres napoléoniennes.','https://www.rmg.co.uk/collections/objects/rmgc-object-12042','turn183search3','Royal Museums Greenwich')
add('10-22','CUB','La crise des missiles devient publique',1962,'Le 22 octobre 1962, John F. Kennedy annonce publiquement la présence de missiles soviétiques à Cuba. L’île est au centre d’une confrontation majeure de la guerre froide.','https://microsites.jfklibrary.org/cmc/oct22/index.html','turn183search1','John F. Kennedy Presidential Library')
add('10-23','HUN','Le soulèvement hongrois',1956,'Le 23 octobre 1956, des manifestations à Budapest ouvrent le soulèvement hongrois. Les revendications de liberté et d’indépendance se heurtent ensuite à l’intervention soviétique.','https://november4.kormany.hu/about-the-memorial-day','turn183search2','Gouvernement hongrois — site commémoratif')
add('10-24','ZMB','L’indépendance de la Zambie',1964,'La Rhodésie du Nord devient indépendante le 24 octobre 1964 sous le nom de Zambie. Cette date marque la fin de l’administration coloniale britannique.','https://history.state.gov/countries/zambia','turn172view5','Office of the Historian')
add('10-25','KAZ','La déclaration de souveraineté du Kazakhstan',1990,'Le 25 octobre 1990, la république soviétique kazakhe adopte une déclaration de souveraineté. Ce jalon précède l’indépendance, proclamée en décembre 1991.','https://history-state.kz/en/the-declaration-on-state-sovereignty-the-herald-of-kazakhstan-s-genuine-independence/','turn184search23','Institut d’histoire de l’État du Kazakhstan')
add('10-26','AUT','L’Autriche adopte sa neutralité',1955,'Le 26 octobre 1955, le Parlement autrichien adopte la loi constitutionnelle sur la neutralité permanente. Cette décision suit le rétablissement de la pleine souveraineté du pays.','https://www.bmeia.gv.at/oev-wien/about-austria/history','turn184search1','Ministère autrichien des Affaires étrangères')
add('10-27','VCT','L’indépendance de Saint-Vincent-et-les-Grenadines',1979,'Saint-Vincent-et-les-Grenadines devient indépendant le 27 octobre 1979. L’archipel des Caraïbes cesse d’être un territoire britannique.','https://www.gov.vc/index.php/visitors/about-svg','turn184search4','Gouvernement de Saint-Vincent-et-les-Grenadines')
add('10-28','CZE','La naissance de la Tchécoslovaquie',1918,'Le 28 octobre 1918, l’indépendance de la Tchécoslovaquie est proclamée. Ce nouvel État réunit notamment les pays tchèques et la Slovaquie à la fin de la Première Guerre mondiale.','https://mzv.gov.cz/jnp/en/issues_and_press/archive/events_and_issues/x2011/czechoslovak_independence_day.html','turn184search0','Ministère tchèque des Affaires étrangères')
add('10-29','TUR','La proclamation de la République turque',1923,'La République turque est proclamée le 29 octobre 1923. Mustafa Kemal devient son premier président ; cette transformation institutionnelle suit la guerre d’indépendance.','https://www.ktb.gov.tr/EN-103934/1923.html','turn186search0','Ministère turc de la Culture et du Tourisme')
add('10-30','SVK','La déclaration de Martin',1918,'Le 30 octobre 1918, des représentants slovaques réunis à Martin soutiennent l’union des Slovaques et des Tchèques. Cette déclaration accompagne la naissance de la Tchécoslovaquie.','https://www.prezident.sk/en/short-history/','turn189search5','Présidence slovaque')
add('10-31','DEU','Les 95 thèses de Luther',1517,'Le 31 octobre 1517, Martin Luther transmet ses 95 thèses à l’archevêque de Mayence. Ce texte devient un jalon de la Réforme. L’affichage sur une porte d’église reste historiquement discuté.','https://www.deutschlandmuseum.de/en/history/calendar/1517-10-31-95-theses/','turn186search19','Deutschlandmuseum')
add('11-01','DZA','Le début de la guerre d’Algérie',1954,'L’insurrection du 1er novembre 1954 marque le début de la guerre d’Algérie. Le conflit conduit à l’indépendance du pays en 1962.','https://www.elysee.fr/emmanuel-macron/2024/11/01/commemoration-du-1er-novembre-2024-70eme-anniversaire-du-declenchement-de-linsurrection-du-1er-novembre-1954','turn189search2','Présidence de la République française')
add('11-02','ETH','Le couronnement de Haïlé Sélassié',1930,'Haïlé Sélassié est couronné empereur d’Éthiopie le 2 novembre 1930 à Addis-Abeba. Son règne constitue une longue période de l’histoire éthiopienne du XXe siècle.','https://blog.nationalmuseum.ch/en/2022/01/emperor-haile-selassie-god-of-the-rastafarians/','turn189search6','Musée national suisse')
add('11-15','BRA','La proclamation de la République brésilienne',1889,'Le 15 novembre 1889, la république est proclamée au Brésil. Ce changement de régime met fin à la monarchie impériale.','https://www2.camara.leg.br/a-camara/conheca/historia/a1republica.html/','Vérification primaire transmise par agent parent','Chambre des députés du Brésil')
Path('editorial15/calendar_q4.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
